CREATE TABLE IF NOT EXISTS content (id TEXT PRIMARY KEY,kind TEXT NOT NULL,status TEXT NOT NULL,data TEXT NOT NULL,source TEXT NOT NULL,source_label TEXT NOT NULL,demo INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS members (id TEXT PRIMARY KEY,session_hash TEXT UNIQUE NOT NULL,nickname TEXT UNIQUE NOT NULL,answers TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS votes (content_id TEXT NOT NULL REFERENCES content(id),member_id TEXT NOT NULL REFERENCES members(id),created_at TEXT NOT NULL,PRIMARY KEY(content_id,member_id));
CREATE TABLE IF NOT EXISTS agent_keys (id TEXT PRIMARY KEY,name TEXT NOT NULL,key_hash TEXT UNIQUE NOT NULL,prefix TEXT NOT NULL,created_at TEXT NOT NULL,last_used_at TEXT,revoked_at TEXT);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit (id INTEGER PRIMARY KEY,action TEXT NOT NULL,subject TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (session_hash TEXT PRIMARY KEY,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS management_sessions (session_hash TEXT PRIMARY KEY,expires_at INTEGER NOT NULL,role TEXT NOT NULL CHECK(role IN ('super_admin','operator')));
CREATE TABLE IF NOT EXISTS rate_limits (key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS rate_limits_expiry ON rate_limits(expires_at);
CREATE TABLE IF NOT EXISTS member_accounts (member_id TEXT PRIMARY KEY REFERENCES members(id),nickname TEXT NOT NULL,wechat_id TEXT NOT NULL COLLATE NOCASE UNIQUE,password_hash TEXT NOT NULL,password_salt TEXT NOT NULL,password_scheme TEXT NOT NULL,joined_at TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS member_sessions (session_hash TEXT PRIMARY KEY,member_id TEXT NOT NULL REFERENCES member_accounts(member_id),expires_at INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS member_sessions_member ON member_sessions(member_id);
CREATE INDEX IF NOT EXISTS member_sessions_expiry ON member_sessions(expires_at);
